func (v AccessValue) Equal(o attr.Value) bool {
	other, ok := o.(AccessValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Blueprints.Equal(other.Blueprints) {
		return false
	}

	if !v.CatalogItemTypes.Equal(other.CatalogItemTypes) {
		return false
	}

	if !v.Clouds.Equal(other.Clouds) {
		return false
	}

	if !v.Features.Equal(other.Features) {
		return false
	}

	if !v.Groups.Equal(other.Groups) {
		return false
	}

	if !v.InstanceTypes.Equal(other.InstanceTypes) {
		return false
	}

	if !v.Personas.Equal(other.Personas) {
		return false
	}

	if !v.ReportTypes.Equal(other.ReportTypes) {
		return false
	}

	if !v.Tasks.Equal(other.Tasks) {
		return false
	}

	if !v.VdiPools.Equal(other.VdiPools) {
		return false
	}

	if !v.Workflows.Equal(other.Workflows) {
		return false
	}

	return true
}

